                f"{what}.depends_on must contain only non-empty strings"
            )
        if dep in seen_deps:
            raise ValueError(f"{what}.depends_on has duplicate entry: {dep!r}")
        seen_deps.add(dep)
        deps.append(dep)
    return _Stage(stage_id, name, logic, parsed_requires, tuple(deps))


